<template>
  <q-page class="tests-page q-pa-md">
    <!-- Page Header with Environment Badge -->
    <div class="page-header q-mb-lg">
      <div class="row items-center justify-between">
        <div class="col-auto">
          <div class="row items-center q-gutter-md">
            <div>
              <h4 class="text-h4 q-my-none">Test Results</h4>
              <p class="text-grey-7 q-mt-sm q-mb-none">
                Current status for {{ currentEnvironment }} environment
              </p>
              <p v-if="lastFetchedAt" class="text-grey-6 text-caption q-mb-none">
                <q-icon name="schedule" size="xs" class="q-mr-xs" />
                Updated: {{ formatTime(lastFetchedAt) }}
              </p>
            </div>
            <q-chip
              :color="getEnvironmentColor(currentEnvironment)"
              text-color="white"
              size="lg"
              class="text-bold"
            >
              {{ currentEnvironment.toUpperCase() }}
            </q-chip>
          </div>
        </div>
        <div class="col-auto">
          <q-btn
            v-if="aggregatedTestTotals"
            :color="aggregatedTestTotals.allPassing ? 'positive' : 'negative'"
            :icon="aggregatedTestTotals.allPassing ? 'check_circle' : 'error'"
            :label="
              aggregatedTestTotals.allPassing
                ? `ALL ${aggregatedTestTotals.totalTests} TESTS PASSED`
                : `${aggregatedTestTotals.totalFailed} TESTS FAILED`
            "
            unelevated
            no-caps
            class="text-bold"
          />
        </div>
      </div>
    </div>

    <!-- Service Categories -->
    <div v-if="!loading">
      <div
        v-for="category in serviceCategories"
        :key="category.name"
        class="category-section q-mb-xl"
      >
        <div class="category-header q-mb-md">
          <q-icon :name="category.icon" size="32px" class="q-mr-sm" />
          <h5 class="text-h5 q-my-none">{{ category.displayName }}</h5>
        </div>

        <div class="service-grid row q-col-gutter-md">
          <!-- Render all services in category -->
          <div
            v-for="service in category.services"
            :key="service"
            class="col-12 col-sm-6 col-md-4"
          >
            <ServiceTestCard
              v-if="serviceStatusMap[service]"
              :service="serviceStatusMap[service]"
              @click="navigateToDetails(service)"
            />
            <q-skeleton v-else type="rect" height="150px" />
          </div>
        </div>
      </div>
    </div>

    <!-- Loading State -->
    <div v-if="loading" class="loading-state text-center q-pa-xl">
      <q-spinner size="64px" color="primary" />
      <p class="text-grey-7 q-mt-md">Loading test results...</p>
    </div>

    <!-- Error State -->
    <q-banner v-if="error" class="bg-negative text-white q-mt-md" rounded>
      <template #avatar>
        <q-icon name="error" />
      </template>
      {{ error }}
      <template #action>
        <q-btn flat label="Retry" @click="fetchTestStatus" />
      </template>
    </q-banner>
  </q-page>
</template>

<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { useRouter } from 'vue-router';
import { date } from 'quasar';
import { getCurrentEnvironment } from 'src/pages/APIs';
import {
  webTestsAggregatorService,
  apiTestsAggregatorService,
  docflowTestsAggregatorService,
  authTestsAggregatorService,
  autoAccountingTestsAggregatorService,
  barcodeTestsAggregatorService,
  docnetTestsAggregatorService,
  docoperatorTestsAggregatorService,
  emailImportTestsAggregatorService,
  extractionTestsAggregatorService,
  fulltextTestsAggregatorService,
  importFtpTestsAggregatorService,
  ocrTestsAggregatorService,
  poMatchTestsAggregatorService,
  watchdogTestsAggregatorService,
} from 'src/services/tests';
import type { WebTestsStatus, ApiTestsStatus, DocFlowTestsStatus, AuthTestsStatus, GenericTestsStatus } from 'src/services/tests';
import ServiceTestCard from './Components/ServiceTestCard.vue';

const router = useRouter();

// Detect current environment
const currentEnvironment = computed(() => {
  const env = getCurrentEnvironment();
  return env === 'local' ? 'dev' : env;
});

// Service categories - organized by function
const serviceCategories = [
  {
    name: 'core',
    displayName: 'Core Services',
    icon: 'settings',
    services: ['web', 'api', 'auth'],
  },
  {
    name: 'extraction',
    displayName: 'Extraction & OCR',
    icon: 'document_scanner',
    services: ['extraction', 'ocr', 'fulltext'],
  },
  {
    name: 'integration',
    displayName: 'Integration Services',
    icon: 'cloud_sync',
    services: ['barcode', 'po-match', 'import-ftp', 'email-import', 'watchdog', 'docnet'],
  },
  {
    name: 'workflow',
    displayName: 'Workflow & Automation',
    icon: 'account_tree',
    services: ['docflow', 'auto-accounting', 'docoperator'],
  },
];

// State for all services
const webTestsStatus = ref<WebTestsStatus | null>(null);
const apiTestsStatus = ref<ApiTestsStatus | null>(null);
const docflowTestsStatus = ref<DocFlowTestsStatus | null>(null);
const authTestsStatus = ref<AuthTestsStatus | null>(null);
const autoAccountingTestsStatus = ref<GenericTestsStatus | null>(null);
const barcodeTestsStatus = ref<GenericTestsStatus | null>(null);
const docnetTestsStatus = ref<GenericTestsStatus | null>(null);
const docoperatorTestsStatus = ref<GenericTestsStatus | null>(null);
const emailImportTestsStatus = ref<GenericTestsStatus | null>(null);
const extractionTestsStatus = ref<GenericTestsStatus | null>(null);
const fulltextTestsStatus = ref<GenericTestsStatus | null>(null);
const importFtpTestsStatus = ref<GenericTestsStatus | null>(null);
const ocrTestsStatus = ref<GenericTestsStatus | null>(null);
const poMatchTestsStatus = ref<GenericTestsStatus | null>(null);
const watchdogTestsStatus = ref<GenericTestsStatus | null>(null);

const loading = ref(false);
const error = ref<string | null>(null);
const lastFetchedAt = ref<Date | null>(null);

// Map service names to their status refs for easy lookup
const serviceStatusMap = computed(() => ({
  web: webTestsStatus.value,
  api: apiTestsStatus.value,
  docflow: docflowTestsStatus.value,
  auth: authTestsStatus.value,
  'auto-accounting': autoAccountingTestsStatus.value,
  barcode: barcodeTestsStatus.value,
  docnet: docnetTestsStatus.value,
  docoperator: docoperatorTestsStatus.value,
  'email-import': emailImportTestsStatus.value,
  extraction: extractionTestsStatus.value,
  fulltext: fulltextTestsStatus.value,
  'import-ftp': importFtpTestsStatus.value,
  ocr: ocrTestsStatus.value,
  'po-match': poMatchTestsStatus.value,
  watchdog: watchdogTestsStatus.value,
}));

// Aggregated test totals across ALL services
const aggregatedTestTotals = computed(() => {
  const allStatuses = [
    webTestsStatus.value,
    apiTestsStatus.value,
    docflowTestsStatus.value,
    authTestsStatus.value,
    autoAccountingTestsStatus.value,
    barcodeTestsStatus.value,
    docnetTestsStatus.value,
    docoperatorTestsStatus.value,
    emailImportTestsStatus.value,
    extractionTestsStatus.value,
    fulltextTestsStatus.value,
    importFtpTestsStatus.value,
    ocrTestsStatus.value,
    poMatchTestsStatus.value,
    watchdogTestsStatus.value,
  ].filter(Boolean) as (WebTestsStatus | ApiTestsStatus | DocFlowTestsStatus | AuthTestsStatus | GenericTestsStatus)[];

  if (allStatuses.length === 0) {
    return null;
  }

  const totalTests = allStatuses.reduce((sum, s) => sum + s.totalTests, 0);
  const totalFailed = allStatuses.reduce((sum, s) => sum + s.totalFailed, 0);
  const allPassing = totalFailed === 0;

  return {
    totalTests,
    totalFailed,
    allPassing,
  };
});

// Fetch test status for all services
async function fetchTestStatus() {
  loading.value = true;
  error.value = null;

  try {
    // Fetch test status for all services in parallel
    const [
      webStatus,
      apiStatus,
      docflowStatus,
      authStatus,
      autoAccountingStatus,
      barcodeStatus,
      docnetStatus,
      docoperatorStatus,
      emailImportStatus,
      extractionStatus,
      fulltextStatus,
      importFtpStatus,
      ocrStatus,
      poMatchStatus,
      watchdogStatus,
    ] = await Promise.all([
      webTestsAggregatorService.getWebTestsStatus(currentEnvironment.value),
      apiTestsAggregatorService.getApiTestsStatus(currentEnvironment.value),
      docflowTestsAggregatorService.getDocFlowTestsStatus(currentEnvironment.value),
      authTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      autoAccountingTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      barcodeTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      docnetTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      docoperatorTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      emailImportTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      extractionTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      fulltextTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      importFtpTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      ocrTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      poMatchTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      watchdogTestsAggregatorService.getTestsStatus(currentEnvironment.value),
    ]);

    webTestsStatus.value = webStatus;
    apiTestsStatus.value = apiStatus;
    docflowTestsStatus.value = docflowStatus;
    authTestsStatus.value = authStatus;
    autoAccountingTestsStatus.value = autoAccountingStatus;
    barcodeTestsStatus.value = barcodeStatus;
    docnetTestsStatus.value = docnetStatus;
    docoperatorTestsStatus.value = docoperatorStatus;
    emailImportTestsStatus.value = emailImportStatus;
    extractionTestsStatus.value = extractionStatus;
    fulltextTestsStatus.value = fulltextStatus;
    importFtpTestsStatus.value = importFtpStatus;
    ocrTestsStatus.value = ocrStatus;
    poMatchTestsStatus.value = poMatchStatus;
    watchdogTestsStatus.value = watchdogStatus;

    lastFetchedAt.value = new Date();
  } catch (err) {
    console.error('Failed to fetch tests status:', err);
    error.value = 'Failed to load test results. Please try again.';
  } finally {
    loading.value = false;
  }
}

// Get environment badge color
function getEnvironmentColor(env: string): string {
  const colorMap: Record<string, string> = {
    dev: 'blue-6',
    stage: 'orange-6',
    prod: 'red-6',
    demo: 'purple-6',
    sandbox: 'teal-6',
  };
  return colorMap[env] || 'grey-6';
}

// Format timestamp for display
function formatTime(timestamp: Date): string {
  return date.formatDate(timestamp, 'MMM D, YYYY HH:mm');
}

// Get service display name
function getServiceDisplayName(serviceName: string): string {
  const displayNameMap: Record<string, string> = {
    web: 'Web Application',
    api: 'API Service',
    ocr: 'OCR Service',
    extraction: 'Extraction Service',
    fulltext: 'Fulltext Search',
    'po-match': 'PO Matching',
    barcode: 'Barcode Service',
    docflow: 'DocFlow',
    auth: 'Auth Service',
    'auto-accounting': 'Auto Accounting',
    docnet: 'DocNet',
    docoperator: 'DOCOperator',
    'email-import': 'Email Import',
    'import-ftp': 'Import FTP',
    watchdog: 'WatchDog Service',
  };
  return displayNameMap[serviceName] || serviceName;
}

// Navigate to details page
function navigateToDetails(serviceName: string) {
  router.push(`/tests/${serviceName}`);
}

// Load test status on mount
onMounted(() => {
  fetchTestStatus();
});
</script>

