<template>
  <q-card
    flat
    bordered
    class="service-test-card cursor-pointer"
    @click="$emit('click')"
  >
    <!-- Card Header -->
    <q-card-section class="card-header">
      <div class="row items-center justify-between q-mb-sm">
        <div class="col">
          <div class="text-h6 text-bold">{{ service.displayName }}</div>
        </div>
        <div class="col-auto">
          <q-icon
            :name="service.allPassing ? 'check_circle' : 'error'"
            :color="service.allPassing ? 'positive' : 'negative'"
            size="32px"
          />
        </div>
      </div>

      <!-- Environment Badge -->
      <q-chip
        :color="getEnvironmentColor(service.environment)"
        text-color="white"
        size="sm"
        class="q-mb-sm"
      >
        {{ service.environment.toUpperCase() }}
      </q-chip>
    </q-card-section>

    <q-separator />

    <!-- Status Summary -->
    <q-card-section class="status-summary">
      <div v-if="service.allPassing" class="text-positive text-weight-medium">
        <q-icon name="check_circle" size="sm" class="q-mr-xs" />
        All {{ service.totalTests }} tests passed
      </div>
      <div v-else class="text-negative text-weight-medium">
        <q-icon name="error" size="sm" class="q-mr-xs" />
        {{ service.totalFailed }} of {{ service.totalTests }} tests failed
      </div>

      <!-- Test Categories Breakdown -->
      <div class="categories-breakdown q-mt-md">
        <div class="text-caption text-grey-7 q-mb-xs">Test Categories:</div>
        <div class="row q-col-gutter-xs">
          <div
            v-for="category in service.categories"
            :key="category.name"
            class="col-auto"
          >
            <q-chip
              :color="getCategoryChipColor(category)"
              text-color="white"
              size="xs"
              dense
              :icon="getCategoryChipIcon(category)"
            >
              {{ getCategoryChipLabel(category) }}
            </q-chip>
          </div>
        </div>
      </div>
    </q-card-section>

    <q-separator />

    <!-- Card Footer -->
    <q-card-section class="card-footer">
      <div class="text-caption text-grey-7">
        <q-icon name="schedule" size="xs" class="q-mr-xs" />
        <template v-if="latestReportTime">
          Last run: {{ formatTime(latestReportTime) }}
        </template>
        <template v-else>
          No report data available
        </template>
      </div>
    </q-card-section>
  </q-card>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { date } from 'quasar';
import type {
  WebTestsStatus,
  ApiTestsStatus,
  DocFlowTestsStatus,
  AuthTestsStatus,
  GenericTestsStatus,
  TestCategoryStatus,
} from 'src/services/tests';

interface Props {
  service: WebTestsStatus | ApiTestsStatus | DocFlowTestsStatus | AuthTestsStatus | GenericTestsStatus;
}

const props = defineProps<Props>();
defineEmits<{
  (e: 'click'): void;
}>();

// Get the latest report time from all categories (when tests were actually run in Allure)
const latestReportTime = computed((): Date | null => {
  const times = props.service.categories
    .map(cat => cat.lastRunAt)
    .filter((t): t is Date => t !== null);

  if (times.length === 0) return null;

  // Return the most recent time
  return times.reduce((latest, current) =>
    current > latest ? current : latest
  );
});

function getEnvironmentColor(env: string): string {
  const colorMap: Record<string, string> = {
    dev: 'blue-6',
    stage: 'orange-6',
    prod: 'red-6',
    demo: 'purple-6',
    sandbox: 'teal-6',
  };
  return colorMap[env] || 'grey-6';
}

function formatTime(timestamp: Date): string {
  return date.formatDate(timestamp, 'MMM D, YYYY HH:mm');
}

/**
 * Determine if category has data available
 * Uses hasData field if present, otherwise fallback to checking totalTests
 */
function categoryHasData(category: TestCategoryStatus): boolean {
  if (category.hasData !== undefined) {
    return category.hasData;
  }
  // Fallback for services that don't set hasData: consider it has data if totalTests > 0
  return category.totalTests > 0;
}

/**
 * Get chip color based on category status
 * - Grey for N/A (no data)
 * - Positive for passing
 * - Negative for failing
 */
function getCategoryChipColor(category: TestCategoryStatus): string {
  if (!categoryHasData(category)) {
    return 'grey-6';
  }
  return category.allPassing ? 'positive' : 'negative';
}

/**
 * Get chip icon based on category status
 * - No icon for N/A
 * - Check for passing
 * - Close for failing
 */
function getCategoryChipIcon(category: TestCategoryStatus): string | undefined {
  if (!categoryHasData(category)) {
    return undefined;
  }
  return category.allPassing ? 'check' : 'close';
}

/**
 * Get chip label with N/A suffix if no data
 */
function getCategoryChipLabel(category: TestCategoryStatus): string {
  if (!categoryHasData(category)) {
    return `${category.displayName} (N/A)`;
  }
  return category.displayName;
}
</script>

